package com.edufox.schoolerp.transport.work.transport;
import com.edufox.schoolerp.transport.report.transport_report.*;
import com.edufox.schoolerp.transport.work.student_transport.*;

import com.edufox.schoolerp.config.DatabaseWriteGuard;
import io.jsonwebtoken.Claims;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

import java.util.*;

@RestController
@RequestMapping("/api/transport")
@RequiredArgsConstructor
@PreAuthorize("hasRole('FACULTY')")
public class TransportController {
    private final JdbcTemplate jdbc;
    private final DatabaseWriteGuard writeGuard;
    private static String school(Authentication a){return String.valueOf(((Claims)a.getDetails()).get("schoolId"));}
    private static String staff(Authentication a){return String.valueOf(((Claims)a.getDetails()).get("staffUid"));}
    private static String s(Object v){return v==null?"":String.valueOf(v).trim();}
    private static int i(Object v){if(v==null||s(v).isBlank())return 0;if(v instanceof Boolean b)return b?1:0;if("true".equalsIgnoreCase(s(v)))return 1;if("false".equalsIgnoreCase(s(v)))return 0;return Integer.parseInt(s(v));}
    private static double number(Object v){if(v==null||s(v).isBlank())return 0d;return Double.parseDouble(s(v));}
    private static List<Integer> ints(Object raw){List<Integer> out=new ArrayList<>();if(raw instanceof Collection<?> c)for(Object value:c){int n=i(value);if(n>0)out.add(n);}return out;}
    private static Object value(Map<String,Object> values,String key,Object fallback){return values.containsKey(key)&&values.get(key)!=null?values.get(key):fallback;}
    private static Map<String,Object> row(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n+1<v.length;n+=2)m.put(String.valueOf(v[n]),v[n+1]);return m;}
    private String effectiveSession(String schoolId,String requested){String value=s(requested);if(!value.isBlank()&&!"0".equals(value))return value;List<String> rows=jdbc.query("SELECT TOP 1 session FROM TB_Session WHERE school_id=? ORDER BY CASE WHEN status='Default' THEN 0 ELSE 1 END,session DESC",(rs,n)->rs.getString(1),schoolId);return rows.isEmpty()?"":s(rows.get(0));}
    private void cloneTransportInstallments(String schoolId,String session,int feeHeadId,String staffUid){jdbc.update("INSERT INTO Installment_Master(installment_no,fee_type_id,month_id,due_date,created_by,school_id,session,fee_head_id) SELECT DISTINCT im.installment_no,im.fee_type_id,im.month_id,im.due_date,?,im.school_id,im.session,? FROM Installment_Master im WHERE im.school_id=? AND im.session=? AND im.fee_type_id=6 AND (im.fee_head_id=0 OR im.fee_head_id IS NULL) AND NOT EXISTS(SELECT 1 FROM Installment_Master x WHERE x.school_id=im.school_id AND x.session=im.session AND x.fee_type_id=6 AND x.fee_head_id=? AND x.installment_no=im.installment_no AND x.month_id=im.month_id)",staffUid,feeHeadId,schoolId,session,feeHeadId);}

    @GetMapping("/bootstrap") public Map<String,Object> bootstrap(Authentication a){String sc=school(a);Map<String,Object>o=new LinkedHashMap<>();
        o.put("sessions",jdbc.queryForList("SELECT session AS value,session AS label,status FROM TB_Session WHERE school_id=? ORDER BY CASE WHEN status='Default' THEN 0 ELSE 1 END,session DESC",sc));
        o.put("classes",jdbc.queryForList("SELECT c.sec_id AS id,c.class_id AS classId,cn.class_name+' ('+c.section+')' AS label,cn.class_name AS className,c.section FROM TB_Class c JOIN class_name cn ON cn.id=c.class_id AND cn.school_id=c.school_id WHERE c.school_id=? ORDER BY c.class_id,c.sec_id",sc));
        o.put("routes",jdbc.queryForList("SELECT route_id AS id,route_name AS name,status,charges,Route_order AS routeOrder FROM Route_Detail WHERE school_id=? AND ISNULL(status,1)=1 ORDER BY CAST(dbo.GetNumericValue(route_name) AS int),dbo.RemoveNumericCharacters(route_name)",sc));
        o.put("stoppages",jdbc.queryForList("SELECT stoppage_id AS id,stoppage_name AS name,pick_up_time AS pickupTime,drop_time AS dropTime,SlabId AS slabId,status FROM stoppage_detail WHERE school_id=? AND ISNULL(status,1)=1 ORDER BY stoppage_name",sc));
        o.put("transportTypes",jdbc.queryForList("SELECT transport_type_id AS id,name,status FROM transport_type WHERE school_id=? AND ISNULL(status,1)=1 ORDER BY name",sc));
        o.put("months",jdbc.queryForList("SELECT month_id AS id,s_month AS name,s_month AS label FROM tb_month ORDER BY id"));
        o.put("vehicles",jdbc.queryForList("SELECT id,vehicleno_id AS vehicleId,vehicle_no AS vehicleNo,vehicle_name AS vehicleName,transport_type_id AS transportTypeId,status FROM vehicle_master WHERE school_id=? AND ISNULL(status,1)=1 ORDER BY vehicle_no",sc));
        o.put("slabs",jdbc.queryForList("SELECT SlabID AS id,SlabName AS name FROM SlabMaster WHERE school_id=? ORDER BY SlabID",sc));o.put("schoolId",sc);return o;}

    @GetMapping("/types") public List<Map<String,Object>> types(Authentication a){return jdbc.queryForList("SELECT id,transport_type_id AS transportTypeId,name,status FROM transport_type WHERE school_id=? ORDER BY name",school(a));}
    @PostMapping("/types") public Map<String,Object> addType(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a);jdbc.update("INSERT INTO transport_type(transport_type_id,name,school_id,status) VALUES((SELECT ISNULL(MAX(transport_type_id),0)+1 FROM transport_type WHERE school_id=?),?,?,1)",sc,s(r.get("name")),sc);return row("message","Transport type saved");}
    @PutMapping("/types/{id}") public Map<String,Object> updateType(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE transport_type SET name=? WHERE transport_type_id=? AND school_id=?",s(r.get("name")),id,school(a));return row("message","Transport type updated");}
    @DeleteMapping("/types/{id}") public Map<String,Object> deleteType(@PathVariable int id,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE transport_type SET status=0 WHERE transport_type_id=? AND school_id=?",id,school(a));return row("message","Transport type deleted");}

    @GetMapping("/routes") public List<Map<String,Object>> routes(Authentication a){return jdbc.queryForList("SELECT route_id AS id,route_id AS routeId,route_name AS name,status,charges,Route_order AS routeOrder FROM Route_Detail WHERE school_id=? ORDER BY ISNULL(Route_order,999),route_name",school(a));}
    @PostMapping("/routes") public Map<String,Object> addRoute(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a);String name=s(r.get("name")).toUpperCase();if(name.isBlank())throw new IllegalArgumentException("Route name is required");Integer duplicate=jdbc.queryForObject("SELECT COUNT(1) FROM Route_Detail WHERE school_id=? AND route_name=? AND status=1",Integer.class,sc,name);if(duplicate!=null&&duplicate>0)return row("message","Route Name Already Exists");jdbc.update("INSERT INTO Route_Detail(route_id,route_name,status,school_id,created_by,created_date,modified_by,modified_date,charges,Route_order) VALUES((SELECT ISNULL(MAX(route_id),0)+1 FROM Route_Detail WHERE school_id=?),?,1,?,?,GETDATE(),'',NULL,?,?)",sc,name,sc,staff(a),value(r,"charges",0),value(r,"routeOrder",0));return row("message","Route Created Successfully");}
    @PutMapping("/routes/{id}") public Map<String,Object> updateRoute(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE Route_Detail SET route_name=?,charges=?,Route_order=?,modified_by=?,modified_date=GETDATE() WHERE route_id=? AND school_id=?",s(r.get("name")).toUpperCase(),value(r,"charges",0),value(r,"routeOrder",0),staff(a),id,school(a));return row("message","Route Updated successfully");}
    @DeleteMapping("/routes/{id}") @Transactional public Map<String,Object> deleteRoute(@PathVariable int id,Authentication a){writeGuard.requireWritable();String sc=school(a);Integer used=jdbc.queryForObject("SELECT COUNT(1) FROM fee_student_ledger WHERE school_id=? AND fee_type_id=6 AND fee_head_id IN (SELECT stoppage_id FROM route_stoppage_mapping WHERE school_id=? AND route_id=?)",Integer.class,sc,sc,id);if(used!=null&&used>0)return row("message","Route Assigned to student");jdbc.update("DELETE FROM Route_Detail WHERE school_id=? AND route_id=?",sc,id);return row("message","Route Deleted");}

    @GetMapping("/stoppages") public List<Map<String,Object>> stoppages(@RequestParam(required=false)String session,Authentication a){String sc=school(a),ses=effectiveSession(sc,session);return jdbc.queryForList("SELECT w.stoppage_id AS id,w.stoppage_id AS stoppageId,w.stoppage_name AS name,w.stoppage_name AS stoppage,w.pick_up_time AS pickupTime,w.pick_up_time AS pickup,w.drop_time AS dropTime,sl.SlabName AS slabName,sl.SlabID AS slabId,t.fee_head_id AS feeHeadId,j.fee_charges AS feeCharges,j.fee_charges AS charges,r.name AS type,j.transport_type_id AS transportTypeId,ISNULL(sd.nim,0) AS receiveAmount FROM fee_head_master t JOIN fee_head_charge j ON t.fee_head_id=j.fee_head_id AND t.school_id=j.school_id AND t.session=j.session JOIN transport_type r ON r.transport_type_id=j.transport_type_id AND r.school_id=j.school_id JOIN stoppage_detail w ON w.stoppage_id=j.fee_head_id AND w.school_id=j.school_id LEFT JOIN SlabMaster sl ON sl.SlabID=w.SlabId LEFT JOIN (SELECT fee_head_id,COUNT(*) AS nim FROM stu_headwise_deposit WHERE school_id=? AND session=? AND fee_type_id=6 GROUP BY fee_head_id) sd ON sd.fee_head_id=j.fee_head_id WHERE t.school_id=? AND t.fee_type_id=6 AND j.session=? ORDER BY w.stoppage_id",sc,ses,sc,ses);}
    @PostMapping("/stoppages") @Transactional public Map<String,Object> addStoppage(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a),ses=effectiveSession(sc,s(r.get("session"))),name=s(r.get("name")).toUpperCase();if(name.isBlank())throw new IllegalArgumentException("Stoppage name is required");List<Integer> types=ints(r.get("transportTypeIds"));if(types.isEmpty()&&r.get("transportTypeId")!=null)types.add(i(r.get("transportTypeId")));if(types.isEmpty())throw new IllegalArgumentException("Select Transport type");double charges=number(value(r,"charges",r.get("feeCharges")));int slab=i(r.get("slabId"));List<Integer> existing=jdbc.queryForList("SELECT fee_head_id FROM fee_head_master WHERE fee_head=? AND school_id=? AND session=? AND fee_type_id=6",Integer.class,name,sc,ses);int feeId;if(existing.isEmpty()){feeId=jdbc.queryForObject("SELECT ISNULL(MAX(fee_head_id),0)+1 FROM fee_head_master",Integer.class);jdbc.update("INSERT INTO stoppage_detail(stoppage_id,stoppage_name,school_id,created_by,pick_up_time,drop_time,SlabId) VALUES(?,?,?,?,?,?,?)",feeId,name,sc,staff(a),s(r.get("pickupTime")),s(r.get("dropTime")),slab);Integer order=jdbc.queryForObject("SELECT ISNULL(MAX([order]),0)+1 FROM fee_head_master WHERE school_id=? AND session=?",Integer.class,sc,ses);jdbc.update("INSERT INTO fee_head_master(fee_head_id,fee_head,fee_code,fee_type_id,[order],modified_by,school_id,created_by,session,isoptional,status,created_date,modified_date) VALUES(?,?,?,?,?,?,?,?,?,1,1,GETDATE(),GETDATE())",feeId,name,name,6,order,staff(a),sc,staff(a),ses);cloneTransportInstallments(sc,ses,feeId,staff(a));}else{feeId=existing.get(0);jdbc.update("UPDATE fee_head_master SET status=1,modified_by=?,modified_date=GETDATE() WHERE fee_head_id=? AND school_id=? AND session=? AND fee_type_id=6",staff(a),feeId,sc,ses);}
        for(Integer type:types){Integer count=jdbc.queryForObject("SELECT COUNT(1) FROM fee_head_charge WHERE fee_head_id=? AND transport_type_id=? AND school_id=? AND session=?",Integer.class,feeId,type,sc,ses);if(count!=null&&count>0)jdbc.update("UPDATE fee_head_charge SET status=1,fee_charges=?,modified_by=?,modified_date=GETDATE() WHERE fee_head_id=? AND transport_type_id=? AND school_id=? AND session=?",charges,staff(a),feeId,type,sc,ses);else jdbc.update("INSERT INTO fee_head_charge(fee_head_id,fee_type_id,fee_charges,created_by,school_id,session,class_id,status,school_type,transport_type_id,created_date,modified_date) VALUES(?,6,?,?,?, ?,0,1,1,?,GETDATE(),GETDATE())",feeId,charges,staff(a),sc,ses,type);}return row("message",existing.isEmpty()?"Stoppage Created Successfully":"Stoppage Updated Successfully","id",feeId);}
    @PutMapping("/stoppages/{id}") @Transactional public Map<String,Object> updateStoppage(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a),ses=effectiveSession(sc,s(r.get("session")));int type=i(r.get("transportTypeId"));double charges=number(value(r,"charges",r.get("feeCharges")));jdbc.update("UPDATE stoppage_detail SET stoppage_name=?,pick_up_time=?,drop_time=?,modified_by=?,modified_date=GETDATE(),SlabId=? WHERE school_id=? AND stoppage_id=?",s(r.get("name")).toUpperCase(),s(r.get("pickupTime")),s(r.get("dropTime")),staff(a),i(r.get("slabId")),sc,id);jdbc.update("UPDATE fee_head_master SET fee_head=?,fee_code=?,modified_by=?,modified_date=GETDATE() WHERE school_id=? AND fee_type_id=6 AND fee_head_id=? AND session=?",s(r.get("name")).toUpperCase(),s(r.get("name")).toUpperCase(),staff(a),sc,id,ses);jdbc.update("UPDATE fee_head_charge SET fee_charges=? WHERE fee_head_id=? AND transport_type_id=? AND school_id=? AND session=?",charges,id,type,sc,ses);jdbc.update("UPDATE fee_Assign_Transport_Mapping SET charges=? WHERE school_id=? AND stoppage_id=? AND Assign_id IN (SELECT Assign_id FROM fee_Assign_Transport WHERE school_id=? AND stoppage_id=? AND session=? AND transport_type_id=?)",charges,sc,id,sc,id,ses,type);return row("message","Record Updated successfully");}
    @DeleteMapping("/stoppages/{id}") @Transactional public Map<String,Object> deleteStoppage(@PathVariable int id,Authentication a){writeGuard.requireWritable();String sc=school(a);Integer assigned=jdbc.queryForObject("SELECT COUNT(1) FROM fee_assign_transport WHERE school_id=? AND stoppage_id=?",Integer.class,sc,id);if(assigned!=null&&assigned>0)return row("message","Stoppage Assigned");jdbc.update("DELETE FROM route_stoppage_mapping WHERE school_id=? AND stoppage_id=?",sc,id);jdbc.update("DELETE FROM stoppage_detail WHERE school_id=? AND stoppage_id=?",sc,id);jdbc.update("DELETE FROM fee_head_charge WHERE school_id=? AND fee_type_id=6 AND fee_head_id=?",sc,id);jdbc.update("DELETE FROM installment_master WHERE school_id=? AND fee_type_id=6 AND fee_head_id=?",sc,id);jdbc.update("DELETE FROM fee_head_master WHERE school_id=? AND fee_type_id=6 AND fee_head_id=?",sc,id);return row("message","Stoppage Removed");}

    @GetMapping("/mappings") public List<Map<String,Object>> mappings(@RequestParam int routeId,@RequestParam(required=false)String session,Authentication a){String sc=school(a),ses=effectiveSession(sc,session);return jdbc.queryForList("SELECT m.id,m.route_id AS routeId,m.stoppage_id AS stoppageId,s.stoppage_name AS stoppageName,m.status FROM route_stoppage_mapping m JOIN stoppage_detail s ON s.stoppage_id=m.stoppage_id AND s.school_id=m.school_id WHERE m.school_id=? AND m.route_id=? AND ISNULL(m.status,1)=1 AND EXISTS(SELECT 1 FROM fee_head_master h WHERE h.school_id=s.school_id AND h.session=? AND h.fee_type_id=6 AND h.fee_head_id=s.stoppage_id) AND EXISTS(SELECT 1 FROM fee_Assign_Transport fa WHERE fa.school_id=m.school_id AND fa.route_id=m.route_id AND fa.stoppage_id=m.stoppage_id AND fa.session=? AND ISNULL(fa.status,1)=1) ORDER BY s.stoppage_name",sc,routeId,ses,ses);}
    @GetMapping("/mapping-options") public Map<String,Object> mappingOptions(@RequestParam int routeId,@RequestParam String session,Authentication a){String sc=school(a),ses=effectiveSession(sc,session);List<Map<String,Object>> available=jdbc.queryForList("SELECT s.stoppage_name AS name,s.stoppage_id AS id FROM stoppage_detail s WHERE s.school_id=? AND s.stoppage_id NOT IN (SELECT stoppage_id FROM route_stoppage_mapping WHERE route_id=? AND school_id=? AND ISNULL(status,1)=1) AND s.stoppage_id IN (SELECT fee_head_id FROM fee_head_master WHERE school_id=s.school_id AND session=? AND fee_type_id=6) ORDER BY s.stoppage_name",sc,routeId,sc,ses);List<Map<String,Object>> mapped=mappings(routeId,ses,a);return row("available",available,"mapped",mapped,"session",ses);}
    @PostMapping("/mappings") @Transactional public Map<String,Object> saveMappings(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a),ses=effectiveSession(sc,s(r.get("session")));int route=i(r.get("routeId"));Object raw=r.get("stoppageIds");if(raw instanceof Collection<?>c)for(Object x:c){int stop=i(x);if(stop==0)continue;jdbc.update("IF NOT EXISTS(SELECT 1 FROM route_stoppage_mapping WHERE route_id=? AND school_id=? AND stoppage_id=?) INSERT INTO route_stoppage_mapping(route_id,stoppage_id,school_id,created_by,status,created_date) VALUES(?,?,?, ?,1,GETDATE()) ELSE UPDATE route_stoppage_mapping SET status=1,modified_by=?,modified_date=GETDATE() WHERE route_id=? AND school_id=? AND stoppage_id=?",route,sc,stop,route,stop,sc,staff(a),staff(a),route,sc,stop);cloneTransportInstallments(sc,ses,stop,staff(a));}return row("message","Stoppage mapped");}
    @DeleteMapping("/mappings") public Map<String,Object> deleteMapping(@RequestParam int routeId,@RequestParam int stoppageId,Authentication a){writeGuard.requireWritable();jdbc.update("DELETE FROM route_stoppage_mapping WHERE route_id=? AND stoppage_id=? AND school_id=?",routeId,stoppageId,school(a));return row("message","Stoppage deleted from route");}

    @GetMapping("/vehicles") public List<Map<String,Object>> vehicles(Authentication a){return jdbc.queryForList("SELECT v.id,v.vehicleno_id AS vehicleId,v.vehicle_no AS vehicleNo,v.vehicle_name AS vehicleName,v.transport_type_id AS transportTypeId,COALESCE(t.name,'') AS transportType,v.status FROM vehicle_master v LEFT JOIN transport_type t ON t.transport_type_id=v.transport_type_id AND t.school_id=v.school_id WHERE v.school_id=? AND ISNULL(v.status,1)=1 ORDER BY TRY_CONVERT(int,v.transport_type_id),v.id",school(a));}
    @PostMapping("/vehicles") public Map<String,Object> addVehicle(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a);String no=s(r.get("vehicleNo"));jdbc.update("INSERT INTO vehicle_master(vehicleno_id,transport_type_id,vehicle_no,school_id,created_date,created_by,status,vehicle_name) VALUES(?,?,?,?,GETDATE(),?,1,?)",no,r.get("transportTypeId"),no,sc,staff(a),s(r.get("vehicleName")));return row("message","Vehicle saved");}
    @PutMapping("/vehicles/{id}") public Map<String,Object> updateVehicle(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE vehicle_master SET vehicleno_id=?,transport_type_id=?,vehicle_no=?,vehicle_name=?,modified_by=?,modified_date=GETDATE() WHERE id=? AND school_id=?",s(r.get("vehicleNo")),r.get("transportTypeId"),s(r.get("vehicleNo")),s(r.get("vehicleName")),staff(a),id,school(a));return row("message","Vehicle updated");}
    @DeleteMapping("/vehicles/{id}") public Map<String,Object> deleteVehicle(@PathVariable int id,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE vehicle_master SET status=0,modified_by=?,modified_date=GETDATE() WHERE id=? AND school_id=?",staff(a),id,school(a));return row("message","Vehicle deleted");}

    @GetMapping("/drivers") public List<Map<String,Object>> drivers(Authentication a){return jdbc.queryForList("SELECT d.row_id AS id,d.detail_id AS detailId,d.route_id AS routeId,d.vehicleno_id AS vehicleId,(SELECT TOP 1 v.vehicle_no FROM vehicle_master v WHERE v.school_id=d.school_id AND v.status=1 AND v.vehicleno_id=d.vehicleno_id) AS vehicleNo,(SELECT TOP 1 rd.route_name FROM Route_Detail rd WHERE rd.school_id=d.school_id AND rd.route_id=d.route_id AND rd.status=1) AS routeName,(SELECT TOP 1 t.name FROM transport_type t WHERE t.school_id=d.school_id AND t.transport_type_id=d.transport_type_id) AS transportType,d.drivername AS driverName,d.helpername AS helperName,d.transport_type_id AS transportTypeId,CONVERT(varchar(11),d.driver_expiry_date,106) AS driverExpiryDate,CONVERT(varchar(10),d.driver_expiry_date,23) AS driverExpiryDateIso,CONVERT(varchar(11),d.insurance_expiry_date,106) AS insuranceExpiryDate,CONVERT(varchar(10),d.insurance_expiry_date,23) AS insuranceExpiryDateIso,d.mobileno AS mobileNo,d.Ownername AS ownerName,d.upload_document AS uploadDocument FROM driver_vehicle_detail d WHERE d.school_id=? ORDER BY TRY_CONVERT(int,d.transport_type_id),d.row_id",school(a));}
    @PostMapping("/drivers") public Map<String,Object> addDriver(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a);jdbc.update("INSERT INTO driver_vehicle_detail(detail_id,route_id,vehicleno_id,drivername,helpername,transport_type_id,school_id,created_date,created_by,driver_expiry_date,insurance_expiry_date,upload_document,mobileno,Ownername) VALUES((SELECT ISNULL(MAX(detail_id),0)+1 FROM driver_vehicle_detail WHERE school_id=?),?,?,?,?,?,?,GETDATE(),?,?,?,?,?,?)",sc,r.get("routeId"),s(r.get("vehicleId")),s(r.get("driverName")),s(r.get("helperName")),r.get("transportTypeId"),sc,staff(a),s(r.get("driverExpiryDate")),s(r.get("insuranceExpiryDate")),s(r.get("uploadDocument")),s(r.get("mobileNo")),s(r.get("ownerName")));return row("message","Driver vehicle saved");}
    @PutMapping("/drivers/{id}") public Map<String,Object> updateDriver(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE driver_vehicle_detail SET route_id=?,vehicleno_id=?,drivername=?,helpername=?,transport_type_id=?,driver_expiry_date=?,insurance_expiry_date=?,mobileno=?,Ownername=?,modified_by=?,modified_date=GETDATE() WHERE row_id=? AND school_id=?",r.get("routeId"),s(r.get("vehicleId")),s(r.get("driverName")),s(r.get("helperName")),r.get("transportTypeId"),s(r.get("driverExpiryDate")),s(r.get("insuranceExpiryDate")),s(r.get("mobileNo")),s(r.get("ownerName")),staff(a),id,school(a));return row("message","Driver vehicle updated");}
    @DeleteMapping("/drivers/{id}") public Map<String,Object> deleteDriver(@PathVariable int id,Authentication a){writeGuard.requireWritable();jdbc.update("DELETE FROM driver_vehicle_detail WHERE row_id=? AND school_id=?",id,school(a));return row("message","Driver vehicle deleted");}

    @GetMapping("/options") public Map<String,Object> options(@RequestParam String session,@RequestParam(defaultValue="")String routeId,@RequestParam(defaultValue="")String stoppageId,Authentication a){String sc=school(a);List<Map<String,Object>> stops=s(routeId).isBlank()||"0".equals(routeId)?List.of():jdbc.queryForList("SELECT DISTINCT s.stoppage_id AS id,s.stoppage_name AS name,s.status FROM stoppage_detail s JOIN route_stoppage_mapping m ON m.stoppage_id=s.stoppage_id AND m.school_id=s.school_id JOIN fee_head_charge f ON f.fee_head_id=s.stoppage_id AND f.school_id=s.school_id AND f.session=? AND f.status=1 WHERE s.school_id=? AND m.route_id=? AND m.status=1 AND ISNULL(s.status,1)=1 ORDER BY s.stoppage_name",session,sc,routeId);List<Map<String,Object>> types=s(stoppageId).isBlank()||"0".equals(stoppageId)?List.of():jdbc.queryForList("SELECT DISTINCT t.transport_type_id AS id,UPPER(t.name) AS name,t.status FROM transport_type t JOIN fee_head_charge f ON f.transport_type_id=t.transport_type_id AND f.school_id=t.school_id WHERE t.school_id=? AND f.session=? AND f.fee_head_id=? AND ISNULL(f.status,1)=1 AND ISNULL(t.status,1)=1 ORDER BY name",sc,session,stoppageId);return row("stoppages",stops,"transportTypes",types);}
    @GetMapping("/route-name") public Map<String,Object> routeName(@RequestParam String query,Authentication a){List<Map<String,Object>> rows=jdbc.queryForList("SELECT TOP 1 route_name AS routeName FROM Route_Detail WHERE school_id=? AND ISNULL(status,1)=1 AND route_name LIKE ? ORDER BY route_name",school(a),"%"+query+"%");return row("routeName",rows.isEmpty()?"":rows.get(0).get("routeName"));}
    @GetMapping("/students-list-exact") public List<Map<String,Object>> studentList(@RequestParam String session,@RequestParam(defaultValue="0")String classId,@RequestParam(defaultValue="Registered")String status,Authentication a){String sc=school(a);StringBuilder q=new StringBuilder("SELECT st.stu_id AS id,st.registration_no AS registrationNo,'('+st.registration_no+')'+UPPER(COALESCE(so.first_name,''))+' '+UPPER(COALESCE(so.mid_name,''))+' '+UPPER(COALESCE(so.last_name,''))+UPPER(COALESCE('--'+so.father_name,''))+UPPER(COALESCE(so.mother_name,'')) AS name FROM TB_StudentMaster st JOIN student_other_info so ON st.registration_no=so.registration_no AND st.uid=so.uid AND st.school_id=so.school_id WHERE st.session=? AND st.school_id=? AND st.status=?");List<Object>p=new ArrayList<>(List.of(session,sc,status));if(!s(classId).isBlank()&&!"0".equals(classId)){q.append(" AND st.sec_id=?");p.add(classId);}q.append(" ORDER BY UPPER(so.first_name)+' '+UPPER(COALESCE(so.mid_name,''))+' '+UPPER(COALESCE(so.last_name,''))");return jdbc.queryForList(q.toString(),p.toArray());}

    @GetMapping("/students") public List<Map<String,Object>> students(@RequestParam String session,@RequestParam(defaultValue="0")String classId,@RequestParam(defaultValue="")String studentId,@RequestParam(defaultValue="Registered")String status,Authentication a){String sc=school(a);StringBuilder q=new StringBuilder("SELECT st.stu_id AS id,st.stu_id AS studentId,st.registration_no AS registrationNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(so.father_name,'') AS fatherName,COALESCE(so.r_address,'') AS address,cn.class_name+' ('+cl.section+')' AS className,st.class_id AS classId,st.sec_id AS secId,fa.Route_id AS routeId,COALESCE(rd.route_name,'') AS routeName,fa.Stoppage_id AS stoppageId,COALESCE(sd.stoppage_name,'') AS stoppageName,fa.transport_type_id AS transportTypeId,COALESCE(tt.name,'') AS transportType FROM TB_StudentMaster st JOIN student_other_info so ON so.uid=st.uid AND so.registration_no=st.registration_no AND so.school_id=st.school_id JOIN TB_Class cl ON cl.sec_id=st.sec_id AND cl.school_id=st.school_id JOIN class_name cn ON cn.id=st.class_id AND cn.school_id=st.school_id LEFT JOIN (SELECT x.* FROM fee_Assign_Transport x JOIN (SELECT school_id,session,stu_id,MAX(id) id FROM fee_Assign_Transport GROUP BY school_id,session,stu_id) z ON z.school_id=x.school_id AND z.session=x.session AND z.stu_id=x.stu_id AND z.id=x.id) fa ON fa.school_id=st.school_id AND fa.session=st.session AND fa.stu_id=st.stu_id LEFT JOIN Route_Detail rd ON rd.school_id=fa.school_id AND rd.route_id=fa.Route_id LEFT JOIN stoppage_detail sd ON sd.school_id=fa.school_id AND sd.stoppage_id=fa.Stoppage_id LEFT JOIN transport_type tt ON tt.school_id=fa.school_id AND tt.transport_type_id=fa.transport_type_id WHERE st.school_id=? AND st.session=? AND st.status=?");List<Object>p=new ArrayList<>(List.of(sc,session,status));if(!s(classId).isBlank()&&!"0".equals(classId)){q.append(" AND st.sec_id=?");p.add(classId);}if(!s(studentId).isBlank()){q.append(" AND (CAST(st.stu_id AS varchar(50))=? OR st.registration_no=?)");p.add(studentId);p.add(studentId);}q.append(" ORDER BY so.first_name,so.mid_name,so.last_name");List<Map<String,Object>> result=jdbc.queryForList(q.toString(),p.toArray());for(Map<String,Object> student:result){List<Map<String,Object>> mapped=jdbc.queryForList("SELECT month_id AS monthId,paid_status AS paidStatus FROM fee_Assign_Transport_Mapping WHERE school_id=? AND stu_id=? AND Assign_id=(SELECT TOP 1 Assign_id FROM fee_Assign_Transport WHERE school_id=? AND session=? AND stu_id=? ORDER BY id DESC)",sc,student.get("studentId"),sc,session,student.get("studentId"));List<Object> selected=new ArrayList<>(),paid=new ArrayList<>();for(Map<String,Object> m:mapped){selected.add(m.get("monthId"));if(i(m.get("paidStatus"))==1)paid.add(m.get("monthId"));}student.put("selectedMonths",selected);student.put("paidMonths",paid);String route=s(student.get("routeId")),stop=s(student.get("stoppageId"));student.put("stops",route.isBlank()?List.of():jdbc.queryForList("SELECT DISTINCT s.stoppage_id AS id,s.stoppage_name AS name FROM stoppage_detail s JOIN route_stoppage_mapping m ON m.stoppage_id=s.stoppage_id AND m.school_id=s.school_id JOIN fee_head_master h ON h.fee_head_id=s.stoppage_id AND h.school_id=s.school_id AND h.session=? AND h.fee_type_id=6 WHERE s.school_id=? AND m.route_id=? AND m.status=1 ORDER BY s.stoppage_name",session,sc,route));student.put("types",stop.isBlank()?List.of():jdbc.queryForList("SELECT DISTINCT t.transport_type_id AS id,UPPER(t.name) AS name FROM transport_type t JOIN fee_head_charge f ON f.transport_type_id=t.transport_type_id AND f.school_id=t.school_id WHERE t.school_id=? AND t.status=1 AND f.fee_head_id=? AND f.session=? AND f.status=1 ORDER BY name",sc,stop,session));}return result;}
    @PostMapping("/assignments/route") @Transactional public Map<String,Object> changeRoute(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE fee_Assign_Transport SET Route_id=? WHERE school_id=? AND session=? AND stu_id=?",i(r.get("routeId")),school(a),s(r.get("session")),i(r.get("studentId")));return row("message","Route changed");}
    @PostMapping("/assignments-legacy") @Transactional public Map<String,Object> saveAssignmentsLegacy(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a),stf=staff(a),session=s(r.get("session"));Object rows=r.get("rows");int count=0;if(rows instanceof Collection<?>c)for(Object raw:c)if(raw instanceof Map<?,?>m&&Boolean.parseBoolean(s(m.get("selected")))){int stu=i(m.get("studentId")),route=i(m.get("routeId")),stop=i(m.get("stoppageId")),type=i(m.get("transportTypeId"));jdbc.update("DELETE FROM fee_Assign_Transport_Mapping WHERE school_id=? AND stu_id=? AND Assign_id IN (SELECT Assign_id FROM fee_Assign_Transport WHERE school_id=? AND session=? AND stu_id=?)",sc,stu,sc,session,stu);jdbc.update("DELETE FROM fee_Assign_Transport WHERE school_id=? AND session=? AND stu_id=?",sc,session,stu);jdbc.update("INSERT INTO fee_Assign_Transport(stu_id,Assign_id,Route_id,Stoppage_id,assign_date,session,created_date,created_by,status,school_id,transport_type_id,vehicleNO) VALUES(?,(SELECT ISNULL(MAX(Assign_id),0)+1 FROM fee_Assign_Transport),?,?,GETDATE(),?,GETDATE(),?,1,?,?,?)",stu,route,stop,session,stf,sc,type,s(m.get("vehicleId")));Integer aid=jdbc.queryForObject("SELECT TOP 1 Assign_id FROM fee_Assign_Transport WHERE school_id=? AND session=? AND stu_id=? ORDER BY id DESC",Integer.class,sc,session,stu);Object months=m.get("months");int monthCount=0;if(months instanceof Collection<?>mc)for(Object mo:mc){jdbc.update("INSERT INTO fee_Assign_Transport_Mapping(Assign_id,stu_id,month_id,school_id,paid_status,stoppage_id,installment_no,charges) VALUES(?,?,?, ?,0,?,?,?)",aid,stu,i(mo),sc,stop,m.get("installmentNo"),m.get("charges"));monthCount++;}if(monthCount==0){jdbc.update("DELETE FROM fee_Assign_Transport_Mapping WHERE Assign_id=? AND school_id=?",aid,sc);jdbc.update("DELETE FROM fee_Assign_Transport WHERE Assign_id=? AND school_id=?",aid,sc);}else count++;}return row("updated",count,"message","Transport assignments saved");}

    @PostMapping("/assignments") @Transactional public Map<String,Object> saveAssignmentsExact(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a),stf=staff(a),session=s(r.get("session"));Object rows=r.get("rows");int count=0;if(rows instanceof Collection<?>c)for(Object raw:c)if(raw instanceof Map<?,?>m&&Boolean.parseBoolean(s(m.get("selected")))){int stu=i(m.get("studentId")),route=i(m.get("routeId")),stop=i(m.get("stoppageId")),type=i(m.get("transportTypeId"));if(route==0||stop==0||type==0)continue;Set<Integer> selected=new HashSet<>();Object months=m.get("months");if(months instanceof Collection<?>mc)for(Object mo:mc)selected.add(i(mo));Set<Integer> paid=new HashSet<>();for(Map<String,Object> pm:jdbc.queryForList("SELECT month_id FROM fee_Assign_Transport_Mapping WHERE school_id=? AND stu_id=? AND paid_status=1",sc,stu))paid.add(i(pm.get("month_id")));int assignId=0;boolean any=false;for(Map<String,Object> mm:jdbc.queryForList("SELECT month_id FROM tb_month ORDER BY id")){int month=i(mm.get("month_id"));assignId=ensureAssignment(sc,stf,session,stu,route,stop,type,assignId);if(paid.contains(month))continue;applyMonth(sc,session,stu,assignId,stop,type,month,selected.contains(month));if(selected.contains(month))any=true;}if(!any)deleteTransport(sc,stf,session,stu);else transportLedger(sc,session,stu,stop,assignId,type);jdbc.update("DELETE FROM fee_assign_transport WHERE stu_id=? AND session=? AND school_id=? AND assign_id NOT IN (SELECT assign_id FROM fee_Assign_Transport_Mapping WHERE stu_id=? AND school_id=?)",stu,session,sc,stu,sc);count++;}return row("updated",count,"message","Record Saved");}

    private int ensureAssignment(String sc,String staffUid,String session,int stu,int route,int stop,int type,int current){List<Map<String,Object>> existing=jdbc.queryForList("SELECT TOP 1 Assign_id FROM fee_Assign_Transport WHERE school_id=? AND stu_id=? AND session=? AND Stoppage_id=? AND Route_id=?",sc,stu,session,stop,route);String vehicle="";if(existing.isEmpty()){List<Map<String,Object>> v=jdbc.queryForList("SELECT TOP 1 vehicleno_id FROM driver_vehicle_detail WHERE school_id=? AND route_id=?",sc,route);if(!v.isEmpty())vehicle=s(v.get(0).get("vehicleno_id"));jdbc.update("INSERT INTO fee_Assign_Transport(assign_id,stu_id,Route_id,Stoppage_id,school_id,session,created_by,transport_type_id,vehicleNO) VALUES((SELECT ISNULL(MAX(assign_id),0)+1 FROM fee_Assign_Transport WHERE school_id=?),?,?,?,?,?,?,?,?)",sc,stu,route,stop,sc,session,staffUid,type,vehicle);return jdbc.queryForObject("SELECT TOP 1 Assign_id FROM fee_Assign_Transport WHERE school_id=? AND stu_id=? AND session=? AND Stoppage_id=? AND Route_id=? ORDER BY id DESC",Integer.class,sc,stu,session,stop,route);}List<Map<String,Object>> v=jdbc.queryForList("SELECT TOP 1 vehicleno_id FROM driver_vehicle_detail WHERE school_id=? AND route_id=? AND transport_type_id=?",sc,route,type);if(!v.isEmpty())vehicle=s(v.get(0).get("vehicleno_id"));jdbc.update("UPDATE fee_Assign_Transport SET transport_type_id=?,vehicleNO=? WHERE school_id=? AND stu_id=? AND session=? AND Stoppage_id=? AND Route_id=?",type,vehicle,sc,stu,session,stop,route);return i(existing.get(0).get("Assign_id"));}

    private void applyMonth(String sc,String session,int stu,int assignId,int stop,int type,int month,boolean selected){List<Map<String,Object>> current=jdbc.queryForList("SELECT TOP 1 id,paid_status FROM fee_Assign_Transport_Mapping WHERE month_id=? AND stu_id=? AND school_id=? AND stoppage_id=?",month,stu,sc,stop);if(selected){int installment=jdbc.queryForObject("SELECT TOP 1 installment_no FROM Installment_Master WHERE school_id=? AND session=? AND fee_head_id=? AND month_id=?",Integer.class,sc,session,stop,month);Double charges=jdbc.queryForObject("SELECT TOP 1 fee_charges FROM fee_head_charge WHERE school_id=? AND session=? AND fee_head_id=? AND transport_type_id=? AND status=1",Double.class,sc,session,stop,type);if(current.isEmpty())jdbc.update("INSERT INTO fee_Assign_Transport_Mapping(Assign_id,month_id,stu_id,school_id,stoppage_id,installment_no,charges) VALUES(?,?,?,?,?,?,?)",assignId,month,stu,sc,stop,installment,charges);else if(i(current.get(0).get("paid_status"))==0)jdbc.update("UPDATE fee_Assign_Transport_Mapping SET Assign_id=?,stoppage_id=?,installment_no=?,charges=? WHERE id=?",assignId,stop,installment,charges,current.get(0).get("id"));}else if(!current.isEmpty()&&i(current.get(0).get("paid_status"))==0){jdbc.update("DELETE FROM fee_Assign_Transport_Mapping WHERE id=?",current.get(0).get("id"));}}

    private void deleteTransport(String sc,String staffUid,String session,int stu){Integer paid=jdbc.queryForObject("SELECT COUNT(1) FROM stu_headwise_deposit WHERE school_id=? AND status='Active' AND session=? AND stu_id=? AND fee_type_id=6",Integer.class,sc,session,stu);if(paid!=null&&paid>0)return;jdbc.update("INSERT INTO fee_student_ledger_log(rowId,stu_id,installment_no,fee_head_id,fee_type_id,head_amount,concession,payable,receive_amount,balance,school_id,session,class_id,logBy) SELECT id,stu_id,installment_no,fee_head_id,fee_type_id,head_amount,concession,payable,receive_amount,balance,school_id,session,class_id,? FROM fee_student_ledger WHERE school_id=? AND stu_id=? AND session=? AND fee_type_id=6",staffUid,sc,stu,session);jdbc.update("INSERT INTO fee_assign_transport_mapping_log(Assign_id,stu_id,month_id,school_id,paid_status,stoppage_id,installment_no,charges,created_by) SELECT Assign_id,stu_id,month_id,school_id,paid_status,stoppage_id,installment_no,charges,? FROM fee_Assign_Transport_Mapping WHERE school_id=? AND stu_id=?",staffUid,sc,stu);jdbc.update("INSERT INTO fee_assign_transport_log(rowid,stu_id,Assign_id,Route_id,stoppage_id,assign_date,session,created_date,created_by,modified_by,status,school_id,transport_type_id,vehicleNO,logBy) SELECT id,stu_id,Assign_id,Route_id,stoppage_id,assign_date,session,created_date,created_by,modified_by,status,school_id,transport_type_id,vehicleNO,? FROM fee_assign_transport WHERE school_id=? AND stu_id=?",staffUid,sc,stu);jdbc.update("DELETE FROM fee_Assign_Transport_Mapping WHERE school_id=? AND stu_id=?",sc,stu);jdbc.update("DELETE FROM fee_assign_transport WHERE school_id=? AND stu_id=?",sc,stu);jdbc.update("DELETE FROM fee_student_ledger WHERE school_id=? AND stu_id=? AND session=? AND fee_type_id=6",sc,stu,session);}

    private void transportLedger(String sc,String session,int stu,int stop,int assignId,int type){Integer existing=jdbc.queryForObject("SELECT COUNT(1) FROM fee_student_ledger WHERE school_id=? AND session=? AND stu_id=? AND fee_type_id=6",Integer.class,sc,session,stu);Integer consider=jdbc.queryForObject("SELECT TOP 1 COALESCE(considerTransport,0) FROM configuration WHERE school_id=?",Integer.class,sc);String base="SELECT DISTINCT im.installment_no FROM Installment_Master im JOIN fee_Assign_Transport_Mapping fm ON fm.month_id=im.month_id AND fm.stu_id=? AND fm.school_id=? AND fm.Assign_id=? WHERE im.school_id=? AND im.session=? AND im.fee_head_id=? AND im.status=1";List<Object> params=new ArrayList<>(List.of(stu,sc,assignId,sc,session,stop));if(consider==null||consider==0)base+=" AND im.fee_type_id=6";List<Integer> inst=jdbc.query(base,params.toArray(),(rs,n)->rs.getInt(1));if(existing==null||existing==0){for(Integer no:inst){String countSql="SELECT COUNT(DISTINCT im.month_id) FROM Installment_Master im JOIN fee_Assign_Transport_Mapping fm ON fm.month_id=im.month_id AND fm.stu_id=? AND fm.school_id=? AND fm.Assign_id=? WHERE im.installment_no=? AND im.session=? AND im.school_id=? AND im.fee_head_id=? AND im.status=1";List<Object> cp=new ArrayList<>(List.of(stu,sc,assignId,no,session,sc,stop));if(consider==null||consider==0)countSql+=" AND im.fee_type_id=6";Integer monthCount=jdbc.queryForObject(countSql,Integer.class,cp.toArray());Double unit=jdbc.queryForObject("SELECT TOP 1 fee_charges FROM fee_head_charge WHERE fee_head_id=? AND school_id=? AND session=? AND transport_type_id=? AND status=1",Double.class,stop,sc,session,type);double charge=(unit==null?0:unit)*(monthCount==null?0:monthCount);if(charge!=0)jdbc.update("IF NOT EXISTS(SELECT 1 FROM fee_student_ledger WHERE school_id=? AND stu_id=? AND installment_no=? AND fee_head_id=?) INSERT INTO fee_student_ledger(stu_id,installment_no,fee_head_id,head_amount,school_id,session,fee_type_id,class_id) SELECT ?,?,?,?, ?,?,6,class_id FROM TB_StudentMaster WHERE school_id=? AND stu_id=?",sc,stu,no,stop,stu,no,stop,charge,sc,session,sc,stu);}}else{jdbc.update("DELETE FROM fee_student_ledger WHERE school_id=? AND session=? AND stu_id=? AND receive_amount=0 AND fee_type_id=6",sc,session,stu);jdbc.update("INSERT INTO fee_student_ledger(stu_id,installment_no,fee_head_id,head_amount,school_id,session,fee_type_id,class_id) SELECT fm.stu_id,fm.installment_no,fm.stoppage_id,SUM(fm.charges),?,?,6,st.class_id FROM fee_Assign_Transport_Mapping fm JOIN TB_StudentMaster st ON st.stu_id=fm.stu_id AND st.school_id=fm.school_id WHERE fm.installment_no NOT IN (SELECT installment_no FROM fee_student_ledger WHERE stu_id=fm.stu_id AND fee_type_id=6 AND receive_amount<>0 AND school_id=?) AND fm.school_id=? AND fm.stu_id=? GROUP BY fm.installment_no,fm.stu_id,fm.stoppage_id,st.class_id",sc,session,sc,sc,stu);}}

    private String assigned(){return " FROM TB_StudentMaster st JOIN student_other_info so ON so.uid=st.uid AND so.registration_no=st.registration_no AND so.school_id=st.school_id JOIN TB_Class cl ON cl.sec_id=st.sec_id AND cl.school_id=st.school_id JOIN class_name cn ON cn.id=st.class_id AND cn.school_id=st.school_id JOIN fee_Assign_Transport fa ON fa.school_id=st.school_id AND fa.session=st.session AND fa.stu_id=st.stu_id LEFT JOIN Route_Detail rd ON rd.route_id=fa.route_id AND rd.school_id=fa.school_id LEFT JOIN stoppage_detail sd ON sd.stoppage_id=fa.stoppage_id AND sd.school_id=fa.school_id";}
    @GetMapping("/reports/assign-route") public List<Map<String,Object>> assignRoute(@RequestParam String session,@RequestParam(defaultValue="0")String classId,@RequestParam(defaultValue="0")String routeId,Authentication a){String q="SELECT ROW_NUMBER() OVER(ORDER BY st.class_id,st.sec_id,so.first_name,st.registration_no) AS sno,st.registration_no AS registrationNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,cn.class_name+' '+cl.section AS className,COALESCE(rd.route_name,'') AS routeName,COALESCE(sd.stoppage_name,'') AS stoppageName"+assigned()+" WHERE st.school_id=? AND st.session=? AND st.status='registered'";List<Object>p=new ArrayList<>(List.of(school(a),session));if(!"0".equals(classId)){q+=" AND st.sec_id=?";p.add(classId);}if(!"0".equals(routeId)){q+=" AND fa.route_id=?";p.add(routeId);}return jdbc.queryForList(q+" ORDER BY st.class_id,st.sec_id,studentName,st.registration_no",p.toArray());}
    @GetMapping("/reports/student") public List<Map<String,Object>> studentReport(@RequestParam String session,@RequestParam(defaultValue="")String classIds,@RequestParam(defaultValue="")String routeIds,@RequestParam(defaultValue="")String slabId,Authentication a){String q="SELECT st.registration_no AS admissionNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(so.father_name,'') AS fatherName,COALESCE(so.mobile,'') AS mobile,cn.class_name+' ('+cl.section+')' AS className,COALESCE(rd.route_name,'') AS routeName,COALESCE(sd.stoppage_name,'') AS stoppageName,COALESCE(sm.SlabName,'') AS slabName,st.stu_id AS studentId"+assigned()+" LEFT JOIN SlabMaster sm ON sm.SlabID=sd.SlabId AND sm.school_id=sd.school_id WHERE st.school_id=? AND st.session=? AND st.status='registered'";List<Object>p=new ArrayList<>(List.of(school(a),session));if(!s(classIds).isBlank())q+=" AND st.sec_id IN ("+classIds.replaceAll("[^0-9,]","")+")";if(!s(routeIds).isBlank())q+=" AND fa.route_id IN ("+routeIds.replaceAll("[^0-9,]","")+")";if(!s(slabId).isBlank()&&!"0".equals(slabId)){q+=" AND sd.SlabId=?";p.add(slabId);}return jdbc.queryForList(q+" ORDER BY st.class_id,st.sec_id,studentName",p.toArray());}
    @GetMapping("/reports/private-students") public List<Map<String,Object>> privateStudents(@RequestParam String session,@RequestParam(defaultValue="")String classIds,Authentication a){String q="SELECT st.sec_id AS secId,st.class_id AS classId,st.stu_id AS studentId,st.registration_no AS admissionNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(so.father_name,'') AS fatherName,COALESCE(so.mobile,'') AS mobile,COALESCE(so.r_address,'') AS address,cn.class_name+' ('+cl.section+')' AS className FROM TB_StudentMaster st JOIN student_other_info so ON so.uid=st.uid AND so.registration_no=st.registration_no AND so.school_id=st.school_id JOIN TB_Class cl ON cl.sec_id=st.sec_id AND cl.school_id=st.school_id JOIN class_name cn ON cn.id=st.class_id AND cn.school_id=st.school_id WHERE st.school_id=? AND st.session=? AND st.status='registered' AND NOT EXISTS(SELECT 1 FROM fee_Assign_Transport_Mapping fm WHERE fm.school_id=st.school_id AND fm.stu_id=st.stu_id AND fm.month_id=MONTH(GETDATE()))";List<Object>p=new ArrayList<>(List.of(school(a),session));if(!s(classIds).isBlank())q+=" AND st.sec_id IN ("+classIds.replaceAll("[^0-9,]","")+")";return jdbc.queryForList(q+" ORDER BY st.class_id,st.sec_id,studentName",p.toArray());}
    @GetMapping("/reports/monthwise") public List<Map<String,Object>> monthwise(@RequestParam String session,@RequestParam(defaultValue="")String classIds,@RequestParam(defaultValue="")String monthId,@RequestParam(defaultValue="")String routeId,@RequestParam(defaultValue="0")String status,Authentication a){String q="SELECT st.stu_id AS studentId,st.registration_no AS admissionNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,cn.class_name+' '+cl.section AS className,cl.class_id AS classId,cl.sec_id AS secId,COALESCE(rd.route_name,'') AS routeName,fa.month_id AS monthId,COALESCE(sd.stoppage_name,'') AS stoppageName,COALESCE(fa.charges,0) AS dueAmount FROM fee_Assign_Transport_Mapping fa JOIN fee_Assign_Transport ft ON ft.Assign_id=fa.Assign_id AND ft.school_id=fa.school_id AND ft.session=? JOIN TB_StudentMaster st ON st.stu_id=fa.stu_id AND st.school_id=fa.school_id AND st.session=ft.session JOIN student_other_info so ON so.registration_no=st.registration_no AND so.school_id=st.school_id JOIN TB_Class cl ON cl.sec_id=st.sec_id AND cl.school_id=st.school_id JOIN class_name cn ON cn.id=st.class_id AND cn.school_id=st.school_id LEFT JOIN Route_Detail rd ON rd.route_id=ft.route_id AND rd.school_id=ft.school_id LEFT JOIN stoppage_detail sd ON sd.stoppage_id=ft.stoppage_id AND sd.school_id=ft.school_id WHERE fa.school_id=?";List<Object>p=new ArrayList<>(List.of(session,school(a)));if(!s(classIds).isBlank())q+=" AND st.sec_id IN ("+classIds.replaceAll("[^0-9,]","")+")";if(!s(monthId).isBlank()&&!"0".equals(monthId)){q+=" AND fa.month_id=?";p.add(monthId);}if(!s(routeId).isBlank()&&!"0".equals(routeId)){q+=" AND ft.route_id=?";p.add(routeId);}if(!"0".equals(status)&&!s(status).isBlank()){q+=" AND st.status=?";p.add(status);}return jdbc.queryForList(q+" ORDER BY st.class_id,st.sec_id,studentName,fa.month_id",p.toArray());}
}
